from pathlib import Path


def replace_once(path, old, new):
    p = Path(path)
    text = p.read_text()
    count = text.count(old)
    if count != 1:
        raise SystemExit(f'guard failed for {path}: expected one occurrence, got {count}')
    p.write_text(text.replace(old, new, 1))

